shader_type spatial;
render_mode unshaded;
uniform vec4 cold_white: source_color = vec4(0.902, 0.969, 0.969, 1.0);
uniform float pad_light_data:hint_range(0.0, 1.0) = 0.0;
void fragment(){
	ALBEDO = mix(vec3(0.0), cold_white.rgb, pad_light_data);
}

func _update_tablet_screen() -> void:
	if _tablet_hold == TabletHold.NONE:
		_tablet_screen_lit = false
	elif _tablet_move_progress == TABLET_MOVE_DONE:
		_tablet_screen_lit = true
	_tablet.set_screen_lit(_tablet_screen_lit)

void fragment() {
    vec3 rust = texture(rust_albedo, UV).rgb;
    float height = texture(wear_mask, UV).r;
    float width = max(wear_softness, MIN_WEAR_SOFTNESS);
    float w = 1.0 - smoothstep(wear_amount - width, wear_amount + width, height);

    ALBEDO = mix(paint_color.rgb, rust, w);
    ROUGHNESS = mix(paint_roughness, RUST_ROUGHNESS, w);
}

void vertex() {
    if (abs(NORMAL.x) > 0.5) {
        UV = VERTEX.zy;
    } else if (abs(NORMAL.y) > 0.5) {
        UV = VERTEX.xz;
    } else {
        UV = VERTEX.xy;
    }

    UV *= texture_scale;
}

shader_type spatial;

uniform sampler2D rust_albedo : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D wear_mask : filter_linear_mipmap, repeat_enable;

group_uniforms paint;
uniform vec4 paint_color : source_color = vec4(0.260, 0.283, 0.190, 1.0);
uniform float paint_roughness : hint_range(0.0, 1.0) = 0.85;

group_uniforms wear;
uniform float wear_amount : hint_range(0.0, 1.0) = 0.1;
uniform float wear_softness : hint_range(0.0, 0.2) = 0.0;

group_uniforms mapping;
uniform float texture_scale : hint_range(0.1, 10.0) = 2.0;

group_uniforms;

const float RUST_ROUGHNESS = 0.79;
const float MIN_WEAR_SOFTNESS = 0.001;

shader_type spatial;
render_mode unshaded;

uniform sampler2D greys_source_color : source_color, filter_nearest;
uniform sampler2D greys_raw : filter_nearest;
uniform bool use_source_color = true;

void fragment() {
    if (use_source_color) {
        ALBEDO = texture(greys_source_color, UV).rgb;
    } else {
        ALBEDO = texture(greys_raw, UV).rgb;
    }
}

// The base color is multiplied by the color texture.
uniform vec4 albedo : source_color;

// source_color converts the texture's sRGB colors to linear values when sampled.
uniform sampler2D texture_albedo : source_color, filter_linear_mipmap, repeat_enable;

// This texture stores surface directions instead of colors.
// hint_roughness_normal identifies the normal map for roughness processing.
uniform sampler2D texture_normal : hint_roughness_normal, filter_linear_mipmap, repeat_enable;

// Controls the strength of the normal map.
uniform float normal_scale : hint_range(-16.0, 16.0);

func _check_sampler_hints(shader_path: String) -> void:
	var source := FileAccess.get_file_as_string(shader_path)
	var re := RegEx.create_from_string("uniform\\s+sampler2D\\s+(\\w+)\\s*(?::\\s*([^;=]*))?\\s*;")
	var found := {}
	for m in re.search_all(source):
		var hints: Array = []
		for h in m.get_string(2).split(",", false):
			hints.append(h.strip_edges())
		found[m.get_string(1)] = hints
	var expected: Dictionary = SAMPLER_HINTS[shader_path]
	_check(found.keys().size() == expected.keys().size(),
		"%s: %d sampler(s) in source (found %s)" % [shader_path.get_file(), expected.size(), found.keys()])
	for sampler_name in expected:
		_check(found.has(sampler_name) and found[sampler_name] == expected[sampler_name],
			"%s: %s hints are %s (source: %s)" % [shader_path.get_file(), sampler_name,
			", ".join(expected[sampler_name]), ", ".join(found.get(sampler_name, ["<missing>"]))])
